def encode(img):
    import math

    def wrap(t):
        return (t + math.pi / 2) % math.pi - math.pi / 2

    def render(p):
        cx, cy, a, b, th = p
        ct, st = math.cos(th), math.sin(th)
        out = []
        for i in range(16):
            for j in range(16):
                dx, dy = j - cx, i - cy
                u, v = dx * ct + dy * st, -dx * st + dy * ct
                rho = math.sqrt((u / a) ** 2 + (v / b) ** 2)
                if rho < 1e-12:
                    d = min(a, b)
                else:
                    d = (1.0 - rho) / math.sqrt((u / (a*a))**2 +
                                                (v / (b*b))**2)
                out.append(max(0.0, min(1.0, 0.5 + d)))
        return out

    def clamp(p):
        return [max(-1.5, min(16.5, p[0])),
                max(-1.5, min(16.5, p[1])),
                max(1.2, min(5.3, p[2])),
                max(1.2, min(5.3, p[3])), wrap(p[4])]

    def evaluate(p):
        q = render(p)
        dot = sum(x*y for x, y in zip(img, q))
        norm = sum(y*y for y in q)
        amp = max(0.3, min(1.2, dot / max(norm, 1e-12)))
        return sum((x - amp*y)**2 for x, y in zip(img, q)), amp

    seeds = []
    for cutoff in (0.16, 0.28, 0.40):
        sw = sx = sy = 0.0
        for i in range(16):
            for j in range(16):
                w = max(0.0, img[16*i+j] - cutoff)
                sw += w
                sx += w*j
                sy += w*i
        if sw < 1e-8:
            continue
        cx, cy = sx/sw, sy/sw
        xx = yy = xy = 0.0
        for i in range(16):
            for j in range(16):
                w = max(0.0, img[16*i+j] - cutoff)
                dx, dy = j-cx, i-cy
                xx += w*dx*dx
                yy += w*dy*dy
                xy += w*dx*dy
        xx, yy, xy = xx/sw, yy/sw, xy/sw
        disc = math.sqrt((xx-yy)**2 + 4*xy*xy)
        th = 0.5*math.atan2(2*xy, xx-yy)
        a = 2*math.sqrt(max(0.25, (xx+yy+disc)*0.5))
        b = 2*math.sqrt(max(0.25, (xx+yy-disc)*0.5))
        seeds.append(clamp([cx, cy, a, b, th]))
    if not seeds:
        seeds = [[7.5, 7.5, 2.7, 2.1, 0.0]]

    best, bestamp = None, 0.8
    besterr = float("inf")
    for start in seeds:
        # Nelder-Mead search handles the correlated shape and orientation parameters.
        scales = [0.35, 0.35, 0.35, 0.35, 0.14]
        simplex = [start[:]]
        for k in range(5):
            p = start[:]
            p[k] += scales[k]
            simplex.append(clamp(p))

        def val(p):
            return evaluate(p)[0]

        for _ in range(220):
            simplex.sort(key=val)
            vals = [val(p) for p in simplex]
            if max(vals) - min(vals) < 1e-10:
                break
            center = [sum(simplex[i][k] for i in range(5))/5.0
                      for k in range(5)]
            worst = simplex[5]
            reflected = clamp([center[k] + (center[k]-worst[k])
                               for k in range(5)])
            fr = val(reflected)
            if fr < vals[0]:
                expanded = clamp([center[k] + 2*(reflected[k]-center[k])
                                  for k in range(5)])
                simplex[5] = expanded if val(expanded) < fr else reflected
            elif fr < vals[4]:
                simplex[5] = reflected
            else:
                if fr < vals[5]:
                    contracted = clamp([center[k] + 0.5*(reflected[k]-center[k])
                                        for k in range(5)])
                else:
                    contracted = clamp([center[k] + 0.5*(worst[k]-center[k])
                                        for k in range(5)])
                if val(contracted) < min(fr, vals[5]):
                    simplex[5] = contracted
                else:
                    for i in range(1, 6):
                        simplex[i] = clamp([simplex[0][k] +
                                            0.5*(simplex[i][k]-simplex[0][k])
                                            for k in range(5)])

        p = min(simplex, key=val)
        # Finish with small coordinate steps to remove simplex residual error.
        steps = [0.08, 0.08, 0.08, 0.08, 0.035]
        err, amp = evaluate(p)
        while max(steps) > 0.004:
            changed = False
            for k in range(5):
                for sign in (-1, 1):
                    q = p[:]
                    q[k] += sign*steps[k]
                    q = clamp(q)
                    e, aa = evaluate(q)
                    if e < err:
                        p, err, amp, changed = q, e, aa, True
            if not changed:
                steps = [s*0.55 for s in steps]
        if err < besterr:
            best, besterr, bestamp = p, err, amp

    return best + [bestamp]


